create function pg_temp.local_snapshot(p_record uuid) returns jsonb language sql as $$
 select jsonb_build_object('source',jsonb_build_object('id',r.id,'financing_type',r.financing_type,'source_dataset',r.source_dataset,'source_record_id',r.source_record_id,'mechanism',r.mechanism,'title',r.title,'provider_name',r.provider_name,'amount',r.amount,'source_payload',r.source_payload),
 'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'url',d.url,'status',d.status,'mime_type',d.mime_type,'text_length',d.text_length,'extraction_method',d.extraction_method,'extraction_coverage',d.extraction_coverage,'quality_flags',d.quality_flags,'extraction_partial',d.extraction_partial,'active_extraction_id',d.active_extraction_id,'storage_path',d.storage_path,'storage_sha256',d.storage_sha256,'extracted_text_hash',d.extracted_text_hash) order by d.id),'[]'::jsonb) from source_documents d where d.source_record_id=r.id),
 'chunks',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'source_document_id',e.source_document_id,'ordinal',e.ordinal,'content_sha256',encode(extensions.digest(e.content,'sha256'),'hex')) order by d.id,e.ordinal,e.id),'[]'::jsonb) from evidence_chunks e join source_documents d on d.id=e.source_document_id where d.source_record_id=r.id and d.status='fetched' and e.extraction_id=d.active_extraction_id)) from source_records r where r.id=p_record
$$;
do $$
declare sid uuid:=gen_random_uuid();other uuid:=gen_random_uuid();run1 uuid;run2 uuid;run3 uuid;run4 uuid;oldjob uuid;newjob uuid;detjob uuid;errjob uuid;doc uuid:=gen_random_uuid();otherdoc uuid:=gen_random_uuid();chunk uuid:=gen_random_uuid();uncited uuid:=gen_random_uuid();foreign_chunk uuid:=gen_random_uuid();e uuid;old_extraction uuid;snapshot jsonb;ok boolean;
 wire_ text:='prepared-json-v1:'||repeat('a',64); response_ jsonb:='{"synthetic":true}';
 data_ jsonb:='{"extracted_title":"original","summary":"Original","confidence":0.8,"engine":"openai-responses-enrichment","engine_version":"mock"}';
begin
 insert into source_records(id,source_dataset,source_record_id,mechanism,title) values(sid,'convenis',sid::text,'Conveni','A'),(other,'convenis',other::text,'Conveni','B');
 insert into pipeline_runs default values returning id into run1;
 insert into pipeline_jobs(run_id,source_record_id,status,created_at) values(run1,sid,'ready','2000-01-01') returning id into oldjob;
 insert into source_documents(id,source_record_id,url,url_hash,document_type,status) values(doc,sid,'https://example.invalid/1',doc::text,'agreement','fetched'),(otherdoc,other,'https://example.invalid/2',otherdoc::text,'agreement','fetched');
 insert into evidence_chunks(id,source_document_id,ordinal,content,content_hash,character_count) values(chunk,doc,0,'synthetic','hash',9),(uncited,doc,1,'not-cited','hash',9),(foreign_chunk,otherdoc,0,'synthetic','hash',9);
 snapshot:=pg_temp.local_snapshot(sid);
 insert into provider_calls(pipeline_job_id,phase,request_hash,state) values(oldjob,'enrichment','historical','received');
 if local_begin_enrichment(oldjob,sid,snapshot) is not false then raise exception 'Historical receipt accepted without intent';end if;
 if exists(select 1 from local_enrichment_attempts where job_id=oldjob) then raise exception 'Ambiguous attempt recorded';end if;
 update provider_calls set state='sending' where pipeline_job_id=oldjob;
 if local_begin_enrichment(oldjob,sid,snapshot) is not false then raise exception 'Uncertain historical call accepted';end if;
 delete from provider_calls where pipeline_job_id=oldjob;
 if local_begin_enrichment(oldjob,sid,snapshot) is not true or local_begin_enrichment(oldjob,sid,snapshot) is not true then raise exception 'Current intent not resumable';end if;
 insert into record_enrichments(source_record_id,summary,confidence,engine,engine_version) values(sid,'Concurrent result',0,'fixture','fixture');
 if local_begin_enrichment(oldjob,sid,snapshot) is not false then raise exception 'Concurrent result did not block provider';end if;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Concurrent result overwritten';end if;
 delete from record_enrichments where source_record_id=sid;
 insert into provider_calls(pipeline_job_id,phase,request_hash,state,response) values(oldjob,'enrichment',wire_,'received',response_);
 if local_begin_enrichment(oldjob,sid,snapshot) is not true then raise exception 'Receipt with current intent did not resume';end if;
 update provider_calls set state='sending' where pipeline_job_id=oldjob;
 if local_commit_enrichment(oldjob,sid,'error',null,null,'PROVIDER_UNKNOWN',snapshot) is not false then raise exception 'Uncertain provider error committed';end if;
 if local_commit_enrichment(oldjob,sid,'complete_no_evidence','{"summary":"none","confidence":0,"engine":"deterministic-evidence-policy","engine_version":"mock"}',array[]::uuid[],null,snapshot) is not false then raise exception 'Uncertain provider deterministic result committed';end if;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Uncertain provider result committed';end if;
 if exists(select 1 from local_enrichment_commits where job_id=oldjob) or (select state from provider_calls where pipeline_job_id=oldjob)<>'sending' then raise exception 'Uncertainty was not preserved';end if;
 if local_begin_enrichment(oldjob,sid,snapshot) is not false then raise exception 'Uncertain call could be repeated';end if;
 update provider_calls set state='received' where pipeline_job_id=oldjob;
 update provider_calls set phase='matching' where pipeline_job_id=oldjob;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Wrong receipt phase accepted';end if;
 update provider_calls set phase='enrichment' where pipeline_job_id=oldjob;
 delete from provider_calls where pipeline_job_id=oldjob;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Missing provider receipt accepted';end if;
 insert into provider_calls(pipeline_job_id,phase,request_hash,state,response) values(oldjob,'enrichment',wire_,'received',response_);
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,'prepared-json-v1:'||repeat('b',64),response_) is not false then raise exception 'Wrong wire hash accepted';end if;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,'{"synthetic":false}') is not false then raise exception 'Different receipt response accepted';end if;
 update pipeline_runs set status='paused' where id=run1;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Paused run committed';end if;
 if local_begin_enrichment(oldjob,sid,snapshot) is not false then raise exception 'Paused run began';end if;
 update pipeline_runs set status='ready' where id=run1;

 ok:=local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_);
 if ok is not true then raise exception 'Current result rejected';end if;
 if local_begin_enrichment(oldjob,sid,snapshot) is not false then raise exception 'Completed attempt could call provider again';end if;
 select id into strict e from record_enrichments where source_record_id=sid;
 if not exists(select 1 from record_enrichment_evidence where enrichment_id=e and evidence_chunk_id=chunk) then raise exception 'Evidence missing';end if;
 ok:=local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_);
 if ok is not true or (select count(*) from record_enrichments where source_record_id=sid)<>1 or (select count(*) from record_enrichment_evidence where enrichment_id=e)<>1 then raise exception 'Exact retry duplicated result';end if;
 update record_enrichments set summary='tampered' where source_record_id=sid;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Altered committed result acknowledged';end if;
 update record_enrichments set summary='Original' where source_record_id=sid;
 update source_records set enrichment_status='error' where id=sid;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Altered committed status acknowledged';end if;
 update source_records set enrichment_status='completed' where id=sid;
 if local_commit_enrichment(oldjob,sid,'complete',jsonb_set(data_,'{summary}','"different"'),array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Changed replay accepted';end if;
 if local_commit_enrichment(oldjob,sid,'error',null,null,'error after success',snapshot) is not false then raise exception 'Error overwrote completed result';end if;
 if (select enrichment_status from source_records where id=sid)<>'completed' or (select summary from record_enrichments where source_record_id=sid)<>'Original' then raise exception 'Divergent retry changed committed result';end if;
 update evidence_chunks set content='changed uncited evidence' where id=uncited;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Changed uncited chunk accepted';end if;
 update evidence_chunks set content='not-cited' where id=uncited;
 -- An in-place content edit leaves extraction_id and stored content_hash alone.
 update evidence_chunks set content='tampered' where id=chunk;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Changed chunk content accepted';end if;
 if local_commit_enrichment(oldjob,sid,'error',null,null,'changed chunk',snapshot) is not false then raise exception 'Changed chunk error accepted';end if;
 if local_commit_enrichment(oldjob,sid,'complete_no_evidence','{"summary":"none","confidence":0,"engine":"deterministic-evidence-policy","engine_version":"mock"}',array[]::uuid[],null,snapshot) is not false then raise exception 'Changed chunk empty result accepted';end if;
 update evidence_chunks set content='synthetic' where id=chunk;
 select active_extraction_id into old_extraction from source_documents where id=doc;
 update source_documents set active_extraction_id=gen_random_uuid() where id=doc;
 if local_commit_enrichment(oldjob,sid,'complete_no_evidence','{"summary":"none","confidence":0,"engine":"deterministic-evidence-policy","engine_version":"mock"}',array[]::uuid[],null,snapshot) is not false then raise exception 'Changed extraction accepted for empty result';end if;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,pg_temp.local_snapshot(sid),wire_,response_) is not false then raise exception 'Changed extraction replay accepted';end if;
 update source_documents set active_extraction_id=old_extraction where id=doc;
 update source_records set source_payload='{"changed":true}' where id=sid;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[chunk],null,snapshot,wire_,response_) is not false then raise exception 'Changed source accepted';end if;
 if local_commit_enrichment(oldjob,sid,'error',null,null,'old source',snapshot) is not false then raise exception 'Changed source error accepted';end if;
 update source_records set source_payload='{}' where id=sid;
 if local_commit_enrichment(oldjob,sid,'complete',data_,array[]::uuid[],null,snapshot,wire_,response_) is not false then raise exception 'Replay without citations accepted';end if;
 insert into pipeline_runs default values returning id into run2;
 insert into pipeline_jobs(run_id,source_record_id,status,created_at) values(run2,sid,'ready','2100-01-01') returning id into newjob;
 update source_records set enrichment_status='processing',enrichment_error=null,processing_status='processant' where id=sid;
 if local_commit_enrichment(oldjob,sid,'error',null,null,'stale') is not false then raise exception 'Stale error accepted';end if;
 if local_commit_enrichment(oldjob,sid,'complete',jsonb_set(data_,'{summary}','"stale"'),array[]::uuid[],null,snapshot,wire_,response_) is not false then raise exception 'Stale result accepted';end if;
 if (select enrichment_status from source_records where id=sid)<>'processing' or (select processing_status from source_records where id=sid)<>'processant' or (select summary from record_enrichments where source_record_id=sid)<>'Original' or not exists(select 1 from record_enrichment_evidence where enrichment_id=e and evidence_chunk_id=chunk) then raise exception 'Stale job changed current shared state';end if;
 if local_begin_enrichment(newjob,sid,snapshot) is not false then raise exception 'Unattributed historical result accepted';end if;
 -- Synthetic already-established intents let the remaining tests exercise
 -- commit fencing; the production role cannot insert these markers directly.
 insert into local_enrichment_attempts(job_id,snapshot_hash) values(newjob,encode(extensions.digest(snapshot::text,'sha256'),'hex'));
 insert into provider_calls(pipeline_job_id,phase,request_hash,state,response) values(newjob,'enrichment',wire_,'received',response_);
 delete from record_enrichments where source_record_id=sid;
 update source_documents set active_extraction_id=gen_random_uuid() where id=doc;
 update local_enrichment_attempts set snapshot_hash=encode(extensions.digest(pg_temp.local_snapshot(sid)::text,'sha256'),'hex') where job_id=newjob;
 begin perform local_commit_enrichment(newjob,sid,'complete',data_,array[chunk],null,pg_temp.local_snapshot(sid),wire_,response_);raise exception 'TEST: old extraction evidence accepted';
 exception when raise_exception then if sqlerrm='TEST: old extraction evidence accepted' then raise;end if;end;
 update source_documents set active_extraction_id=old_extraction where id=doc;
 update local_enrichment_attempts set snapshot_hash=encode(extensions.digest(snapshot::text,'sha256'),'hex') where job_id=newjob;
 begin perform local_commit_enrichment(newjob,sid,'complete',data_,array[foreign_chunk],null,snapshot,wire_,response_);raise exception 'TEST: foreign evidence accepted';
 exception when raise_exception then if sqlerrm='TEST: foreign evidence accepted' then raise;end if;end;
 begin perform local_commit_enrichment(newjob,sid,'complete',data_,array[]::uuid[],null,snapshot,wire_,response_);raise exception 'TEST: no citations accepted';
 exception when raise_exception then if sqlerrm='TEST: no citations accepted' then raise;end if;end;
 if exists(select 1 from record_enrichments where source_record_id=sid) then raise exception 'Failed transaction changed enrichment';end if;
 ok:=local_commit_enrichment(newjob,sid,'complete',jsonb_set(data_,'{summary}','"Nou"'),array[chunk],null,snapshot,wire_,response_);
 if ok is not true or (select summary from record_enrichments where source_record_id=sid)<>'Nou' or (select enrichment_status from source_records where id=sid)<>'completed' then raise exception 'Current result rejected';end if;
 select id into strict e from record_enrichments where source_record_id=sid;
 if local_commit_enrichment(newjob,sid,'error',null,null,'post-success',snapshot) is not false then raise exception 'New result overwritten by error';end if;
 insert into pipeline_runs default values returning id into run3;
 insert into pipeline_jobs(run_id,source_record_id,status,created_at) values(run3,sid,'ready','2200-01-01') returning id into detjob;
 insert into local_enrichment_attempts(job_id,snapshot_hash) values(detjob,encode(extensions.digest(snapshot::text,'sha256'),'hex'));
 delete from record_enrichments where source_record_id=sid;
 data_:='{"summary":"No hi ha evidència oficial llegible i substantiva.","confidence":0,"engine":"deterministic-evidence-policy","engine_version":"substantive-evidence-v2"}';
 ok:=local_commit_enrichment(detjob,sid,'complete_no_evidence',data_,array[]::uuid[],null,snapshot);
 if ok is not true or (select summary from record_enrichments where source_record_id=sid)<>data_->>'summary' or exists(select 1 from record_enrichment_evidence where enrichment_id=e) then raise exception 'Deterministic completion not atomic';end if;
 insert into pipeline_runs default values returning id into run4;
 insert into pipeline_jobs(run_id,source_record_id,status,created_at) values(run4,sid,'ready','2300-01-01') returning id into errjob;
 insert into local_enrichment_attempts(job_id,snapshot_hash) values(errjob,encode(extensions.digest(snapshot::text,'sha256'),'hex'));
 delete from record_enrichments where source_record_id=sid;
 if local_commit_enrichment(errjob,sid,'error',null,null,'no snapshot') is not false then raise exception 'Error without snapshot accepted';end if;
 ok:=local_commit_enrichment(errjob,sid,'error',null,null,'valid',snapshot);
 if ok is not true or (select enrichment_status from source_records where id=sid)<>'error' then raise exception 'Current error not recorded';end if;
 if has_table_privilege('service_role','public.local_enrichment_commits','INSERT') then raise exception 'Direct receipt insertion available';end if;
 if has_table_privilege('service_role','public.local_enrichment_attempts','INSERT') then raise exception 'Direct intent insertion available';end if;
 if has_function_privilege('anon','public.local_commit_enrichment(uuid,uuid,text,jsonb,uuid[],text,jsonb,text,jsonb)','execute') then raise exception 'Public local enrichment write';end if;
end $$;
